const page=document.body.dataset.page||'dashboard';document.querySelector(`[data-view="${page}"]`)?.classList.add('active');document.querySelector(`nav a[href="/${page}"]`)?.classList.add('active');
const json=async(url,options={})=>{const r=await fetch(url,options);const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error?.message||`HTTP ${r.status}`);return data};
const toast=msg=>{const e=document.querySelector('#toast');e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),3500)};
const table=(rows,cols)=>!rows.length?'<p class="hint">暂无记录</p>':`<table><thead><tr>${cols.map(c=>`<th>${c[0]}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${r[c[1]]??''}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const statusPill=value=>{const cls=value==='通过'||value==='success'?'pass':value==='警告'||value==='stale'||value==='stale_fallback'?'warn':value==='不通过'||value==='failed'?'fail':'unknown';return `<span class="status-pill ${cls}">${value||'数据不足，无法判断'}</span>`};
const dataMeta=x=>`<div class="data-meta"><span>来源：${x.source||'数据不足'}</span><span>数据日期：${x.data_date||'数据不足'}</span><span>更新时间：${x.updated_at||'数据不足'}</span><span>状态：${x.data_status||x.status||'数据不足'}</span></div>`;
async function loadBase(){try{const h=await json('/api/v1/health');const s=document.querySelector('#status');s.textContent=h.status==='ok'?'服务正常':'异常';s.classList.add('ok');const [accounts,holdings,status]=await Promise.all([json('/api/v1/accounts'),json('/api/v1/holdings'),json('/api/v1/settings/status')]);const cards=document.querySelector('#account-cards');if(cards)cards.innerHTML=accounts.length?accounts.map(a=>{const hs=holdings.filter(h=>h.account_id===a.id);const value=hs.reduce((n,h)=>n+Number(h.market_value),0);return `<article><small>${a.name} · ID ${a.id}</small><b>总资产 ¥${Number(a.total_assets).toLocaleString()}</b><span>现金 ¥${Number(a.cash).toLocaleString()} · 持仓 ¥${value.toLocaleString()}</span></article>`}).join(''):'<article>尚未创建账户</article>';const sources=document.querySelector('#source-status');if(sources)sources.innerHTML=Object.entries(status).filter(([k])=>k!=='secrets').map(([k,v])=>`<article><small>${k}</small><b>${v}</b></article>`).join('');const ht=document.querySelector('#holdings-table');if(ht)ht.innerHTML=table(holdings,[['代码','symbol'],['名称','name'],['数量','quantity'],['现价','current_price'],['市值','market_value'],['盈亏','unrealized_pnl'],['仓位%','position_pct'],['来源','price_source']]);}catch(e){document.querySelector('#status').textContent='连接失败';toast(e.message)}}
document.querySelector('#account-form')?.addEventListener('submit',async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));try{await json('/api/v1/accounts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});toast('账户创建成功');e.target.reset();loadBase()}catch(x){toast(x.message)}});
document.querySelector('#holding-form')?.addEventListener('submit',async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));['stop_loss_price','sector','buy_reason','invalidation_condition'].forEach(k=>{if(!o[k])o[k]=null});try{await json('/api/v1/holdings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});toast('持仓创建成功');e.target.reset();loadBase()}catch(x){toast(x.message)}});
document.querySelector('#trade-form')?.addEventListener('submit',async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.is_planned=o.is_planned==='true';o.traded_at=new Date().toISOString();o.expectation=null;o.invalidation_condition=null;o.notes=null;try{await json('/api/v1/trades',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});toast('交易记录已保存');e.target.reset();loadPage()}catch(x){toast(x.message)}});
document.querySelector('#market-form')?.addEventListener('submit',async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target)),out=document.querySelector('#market-result');out.innerHTML='<div class="missing-data">正在连接真实数据源…</div>';try{const data=await json(`/api/v1/market/sync?symbol=${o.symbol}&days=${o.days}`,{method:'POST'});out.innerHTML=`<article><small>股票 / 获取状态</small><b>${data.quote.symbol} · ${statusPill(data.status)}</b></article><article><small>当前参考价</small><b>${data.quote.price}</b><span>来源：${data.quote.source}</span></article><article><small>历史数据</small><b>新增 ${data.bars_inserted} 根</b><span>${data.history_source}</span></article><article><small>来源切换</small><b>${data.fallback_used?'已使用备用源':'未切换'}</b><span>更新时间：${new Date().toISOString()}</span></article>`;document.querySelector('#market-json').textContent=JSON.stringify(data,null,2)}catch(x){out.innerHTML=`<div class="missing-data">数据不足，无法判断：${x.message}</div>`;document.querySelector('#market-json').textContent=x.message}});
document.querySelector('#discipline-button')?.addEventListener('click',async()=>{const id=document.querySelector('#review-account').value;try{const data=await json(`/api/v1/discipline/check?account_id=${id}`,{method:'POST'}),out=document.querySelector('#review-result');out.innerHTML=data.length?data.map(x=>`<article class="risk-card ${x.severity==='CRITICAL'?'red':'yellow'}"><b>${x.severity==='CRITICAL'?'严重':'警告'} · ${x.rule}</b><span>${x.message}</span><small>来源：纪律规则 · 数据日期：${new Date().toISOString().slice(0,10)} · 获取状态：成功</small></article>`).join(''):'<div class="conclusion">本次未发现纪律违规。仍需核对数据是否完整和价格是否最新。</div>';document.querySelector('#review-json').textContent=JSON.stringify(data,null,2)}catch(x){toast(x.message)}});
document.querySelector('#daily-button')?.addEventListener('click',async()=>{const id=document.querySelector('#review-account').value;try{const data=await json(`/api/v1/reviews/daily?account_id=${id}`),out=document.querySelector('#review-result');out.innerHTML=[['交易次数',data.trade_count],['计划内交易率',`${data.planned_ratio}%`],['事前计划完整率',`${data.plan_complete_ratio}%`],['纪律事件',data.violation_count],['硬止损触发',data.hard_stop_trigger_count],['最常见违规',data.most_common_violation||'无']].map(x=>`<article class="plan-card"><small>${x[0]}</small><b>${x[1]}</b></article>`).join('')+`<div class="data-meta">来源：交易计划、交易记录、持仓快照与纪律事件 · 数据日期：${data.period_start} · 更新时间：${new Date().toISOString()} · 状态：成功</div>`;document.querySelector('#review-json').textContent=JSON.stringify(data,null,2)}catch(x){toast(x.message)}});
const submitJson=async(form,url)=>{const o=Object.fromEntries(new FormData(form));return json(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})};
document.querySelector('#x-account-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await submitJson(e.target,'/api/v1/x/watch-accounts');toast('关注账号已添加')}catch(x){toast(x.message)}});
document.querySelector('#x-query-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await submitJson(e.target,'/api/v1/x/watch-queries');toast('查询已添加')}catch(x){toast(x.message)}});
document.querySelector('#x-sync-button')?.addEventListener('click',async()=>{try{toast(JSON.stringify(await json('/api/v1/x/sync',{method:'POST'})))}catch(x){toast(x.message)}});
document.querySelector('#ai-form')?.addEventListener('submit',async e=>{e.preventDefault();const id=new FormData(e.target).get('content_id'),out=document.querySelector('#ai-result');try{const data=await json(`/api/v1/ai/analyze/${id}`,{method:'POST'}),r=data.result||data;out.innerHTML=`<article class="plan-card"><b>${r.category||'未分类'} · ${r.information_type||'待验证线索'}</b><span>${r.summary||'数据不足，无法判断'}</span><small>该内容不是一手事实，需核验原始来源。</small></article>`;document.querySelector('#ai-json').textContent=JSON.stringify(data,null,2)}catch(x){out.innerHTML=`<div class="missing-data">数据不足，无法判断：${x.message}</div>`}});
const strategyNames={fixed_stop:'固定止损',moving_average:'技术信号：双均线交叉',batch_buy:'分批买入与止盈止损',trend_filter:'趋势过滤',technical_signals:'技术信号组合'};
function formRules(){const f=document.querySelector('#backtest-form');if(!f)return null;const o=Object.fromEntries(new FormData(f)),stop=Number(o.stop_pct||8),position=Number(o.max_position_pct||20),fast=Number(o.fast||5),slow=Number(o.slow||20),drop=Number(o.batch_drop_pct||3),take=Number(o.take_profit_pct||10);if(o.strategy==='fixed_stop')return{buy:`空仓时买入，目标仓位 ${position}%`,sell:`价格触及初始参考价下方 ${stop}% 时止损`,reentry:'止损后下一交易日按相同规则重新入场'};if(o.strategy==='moving_average')return{buy:`MA${fast} 上穿 MA${slow} 后买入 ${position}% 仓位`,sell:`MA${fast} 下穿 MA${slow} 后卖出`,reentry:'等待下一次新的金叉，不重复追买'};if(o.strategy==='trend_filter')return{buy:`收盘站上 MA${slow} 且 MA${fast} 高于 MA${slow} 时买入`,sell:`收盘跌破 MA${slow} 时卖出`,reentry:'趋势条件再次全部成立才重新入场'};return{buy:`先买 1/3；每下跌 ${drop}% 再买 1/3，最多三批`,sell:`整体盈利 ${take}% 止盈或亏损 ${stop}% 止损`,reentry:'全部退出后下一交易日重新开始第一批'}}
function updateRulePreview(rules=formRules()){const box=document.querySelector('#backtest-rule-preview');if(box&&rules)box.innerHTML=`<article><h4>买入规则</h4>${rules.buy}</article><article><h4>卖出规则</h4>${rules.sell}</article><article><h4>重新入场</h4>${rules.reentry}</article>`}
function drawBacktestChart(id,curves,key){const canvas=document.querySelector(`#${id}`);if(!canvas||!curves?.strategy?.length)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,p={l:58,r:16,t:18,b:30},series=[['baseline','#93a4b1','买入并持有'],['strategy','#d6ad5d','交易规则']],values=series.flatMap(([s])=>curves[s].map(x=>Number(x[key]))).filter(Number.isFinite),min=Math.min(...values),max=Math.max(...values),span=max-min||1,toY=v=>p.t+(max-v)/span*(h-p.t-p.b);ctx.clearRect(0,0,w,h);ctx.fillStyle='#101a23';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#344451';ctx.fillStyle='#aeb9c3';ctx.font='12px sans-serif';for(let i=0;i<5;i++){const y=p.t+i*(h-p.t-p.b)/4,v=max-i*span/4;ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(w-p.r,y);ctx.stroke();ctx.fillText(v.toFixed(key==='equity'?0:2),4,y+4)}series.forEach(([s,color,label],si)=>{const rows=curves[s],step=(w-p.l-p.r)/Math.max(rows.length-1,1);ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();rows.forEach((x,i)=>{const px=p.l+i*step,py=toY(Number(x[key]));i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.stroke();ctx.fillStyle=color;ctx.fillText(label,p.l+si*105,12)});const rows=curves.strategy;ctx.fillStyle='#aeb9c3';ctx.fillText(rows[0].date,p.l,h-8);ctx.fillText(rows.at(-1).date,w-85,h-8)}
const metricValue=(v,suffix='')=>v==null?'—':`${Number(v).toLocaleString(undefined,{maximumFractionDigits:2})}${suffix}`;
function showBacktest(data){const bm=data.baseline.metrics,sm=data.disciplined.metrics,c=data.configuration,r=data.strategy_rules,sample=data.sample,market=Object.entries(data.market_rules).map(([k,v])=>`<div><b>${{t_plus_one:'T+1',price_limit:'涨跌停',suspension:'停牌',volume_limit:'成交量限制'}[k]}</b><br>${v.simulated?'已模拟':'未模拟'} · ${v.detail}</div>`).join(''),rows=[['总收益',bm.total_return_pct,sm.total_return_pct,'%'],['年化收益',bm.annual_return_pct,sm.annual_return_pct,'%'],['最大回撤',bm.max_drawdown_pct,sm.max_drawdown_pct,'%'],['胜率',bm.win_rate_pct,sm.win_rate_pct,'%'],['盈亏比（平均盈利/平均亏损）',bm.profit_loss_ratio,sm.profit_loss_ratio,''],['交易次数',bm.trade_count,sm.trade_count,' 笔'],['平均持仓天数',bm.average_holding_days,sm.average_holding_days,' 天'],['累计持仓天数',bm.total_holding_days,sm.total_holding_days,' 天']],metricRows=rows.map(x=>`<tr><td>${x[0]}</td><td>${metricValue(x[1],x[3])}</td><td>${metricValue(x[2],x[3])}</td></tr>`).join(''),trades=data.trades.map(x=>`<tr><td>${x.trade_no}</td><td>${x.entry_date}<br>${x.exit_date}</td><td>${x.entry_price}<br>${x.exit_price}</td><td>${x.direction}</td><td>${x.entry_reason}<br><span class="hint">退出：${x.exit_reason}</span></td><td>${x.return_pct}%<br>¥${x.pnl}</td><td>${x.holding_days}天</td></tr>`).join('')||'<tr><td colspan="7">没有完成的模拟交易</td></tr>';document.querySelector('#backtest-result').innerHTML=`<div class="result-head"><div><b>${data.symbol} · ${data.strategy.name}</b><br><span class="hint">${c.date_from} ～ ${c.date_to} · ${c.data_frequency} · ${c.adjustment}</span></div><span class="sample-badge ${sample.sufficient?'enough':''}">${sample.label}（${sample.trade_count}笔）</span></div><div class="cards comparison-cards"><article><small>初始资金</small><b>¥${Number(c.initial_cash).toLocaleString()}</b></article><article><small>单次最大仓位</small><b>${c.position_size_pct}%</b></article><article><small>手续费 / 滑点</small><b>${c.commission_pct}% / ${c.slippage_pct}%</b><span>均为单边</span></article><article><small>基准</small><b>${data.baseline.name}</b><span>${data.baseline.definition}</span></article></div><div class="rule-box"><article><h4>买入规则</h4>${r.buy}</article><article><h4>卖出规则</h4>${r.sell}</article><article><h4>重新入场</h4>${r.reentry}</article></div><div class="table-wrap"><table class="metric-table"><thead><tr><th>指标</th><th>${data.baseline.name}</th><th>${data.disciplined.name}</th></tr></thead><tbody>${metricRows}</tbody></table></div><div class="curve-grid"><div class="curve-panel"><h3>资金曲线</h3><canvas id="equity-curve" width="650" height="280"></canvas></div><div class="curve-panel"><h3>回撤曲线</h3><canvas id="drawdown-curve" width="650" height="280"></canvas></div></div><h3>市场制度模拟说明</h3><div class="rule-status">${market}</div><div class="warning">${data.warnings.map(x=>`<div>• ${x}</div>`).join('')}</div><div class="conclusion"><b>普通中文结论：</b>${data.conclusion}</div><h3>每笔模拟交易</h3><div class="table-wrap"><table><thead><tr><th>#</th><th>买入 / 卖出日期</th><th>买入 / 卖出价格</th><th>方向</th><th>原因</th><th>收益</th><th>持仓</th></tr></thead><tbody>${trades}</tbody></table></div>`;document.querySelector('#backtest-json').textContent=JSON.stringify(data,null,2);document.querySelector('#backtest-developer').open=false;requestAnimationFrame(()=>{drawBacktestChart('equity-curve',data.curves,'equity');drawBacktestChart('drawdown-curve',data.curves,'drawdown_pct')})}
document.querySelector('#backtest-form')?.addEventListener('input',()=>updateRulePreview());
document.querySelector('#backtest-form')?.addEventListener('submit',async e=>{e.preventDefault();const raw=Object.fromEntries(new FormData(e.target)),payload={symbol:raw.symbol,strategy:raw.strategy,date_from:raw.date_from,date_to:raw.date_to,cash:raw.cash,commission:Number(raw.commission_pct)/100,slippage:Number(raw.slippage_pct)/100,parameters:{stop_pct:Number(raw.stop_pct)/100,fast:Number(raw.fast),slow:Number(raw.slow),max_position:Number(raw.max_position_pct)/100,batch_drop:Number(raw.batch_drop_pct)/100,take_profit:Number(raw.take_profit_pct)/100}},out=document.querySelector('#backtest-result');out.innerHTML='<p>正在计算历史交易、资金曲线和回撤…</p>';try{showBacktest(await json('/api/v1/backtests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}));loadPage()}catch(x){out.innerHTML=`<div class="warning">${x.message}</div>`}});
let companyResearchSymbol='';
let r;
const sourceMeta=x=>x?.source?`<div class="research-meta"><span>报告期：${x.report_period||x.trade_date||'暂无可靠数据'}</span><span>更新时间：${x.updated_at||'暂无可靠数据'}</span>${x.source_url?`<a class="source-link" href="${x.source_url}" target="_blank" rel="noopener">来源：${x.source} ↗</a>`:`<span>来源：${x.source}</span>`}</div>`:'';
const researchMissing=message=>`<div class="missing-data">${message||'暂无可靠数据'}</div>`;
function drawResearchChart(id,rows,series,scale=1){const canvas=document.querySelector(`#${id}`);if(!canvas||!rows?.length)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,p={l:60,r:14,t:20,b:34},values=series.flatMap(s=>rows.map(x=>Number(x[s.key])/scale)).filter(Number.isFinite);if(!values.length)return;const min=Math.min(0,...values),max=Math.max(...values),span=max-min||1,toY=v=>p.t+(max-v)/span*(h-p.t-p.b),step=(w-p.l-p.r)/Math.max(rows.length-1,1);ctx.fillStyle='#101a23';ctx.fillRect(0,0,w,h);ctx.font='12px sans-serif';ctx.strokeStyle='#344451';ctx.fillStyle='#aeb9c3';for(let i=0;i<5;i++){const y=p.t+i*(h-p.t-p.b)/4,v=max-i*span/4;ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(w-p.r,y);ctx.stroke();ctx.fillText(v.toFixed(1),3,y+4)}series.forEach((s,index)=>{ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.beginPath();let started=false;rows.forEach((x,i)=>{const value=Number(x[s.key])/scale;if(!Number.isFinite(value))return;const px=p.l+i*step,py=toY(value);started?ctx.lineTo(px,py):ctx.moveTo(px,py);started=true});ctx.stroke();ctx.fillStyle=s.color;ctx.fillText(s.name,p.l+index*105,13)});ctx.fillStyle='#aeb9c3';ctx.fillText(rows[0].period,p.l,h-8);ctx.fillText(rows.at(-1).period,w-82,h-8)}
function showCompanyReport(data){const f=data.financial,risk=data.risk_radar,val=data.valuation,industry=data.industry_logic,company=data.company;document.querySelector('#company-overview').innerHTML=`<div class="cards"><article><small>公司</small><b>${company.name||data.symbol}</b><span>${data.symbol} · ${company.market||'暂无可靠数据'}</span></article><article><small>行业</small><b>${company.industry||'暂无可靠数据'}</b></article><article><small>数据更新时间</small><b>${data.updated_at||'暂无可靠数据'}</b></article></div><p class="hint">${data.data_notice}</p>`;document.querySelector('#financial-conclusions').innerHTML=f.status==='success'?`${f.conclusions.map(x=>`<div class="conclusion">${x}</div>`).join('')}${sourceMeta(f)}`:researchMissing(f.message);document.querySelector('#financial-trends').innerHTML=f.status==='success'?f.trends.map(x=>`<article><small>${x.name}</small><b>${x.display}</b><span>${x.explanation}</span></article>`).join(''):'';document.querySelector('#financial-anomalies').innerHTML=f.anomalies?.map(x=>`<article class="risk-card ${x.level==='红'?'red':x.level==='黄'?'yellow':'gray'}"><b>${x.level} · ${x.title}</b><span>${x.explanation}</span><small>${x.report_period} · ${x.source} · ${x.updated_at}</small></article>`).join('')||researchMissing();document.querySelector('#risk-summary').innerHTML=r.status==='success'?['红','黄','灰'].map(level=>`<article><small>${level}色事项</small><b>${r.counts[level]||0}</b></article>`).join(''):researchMissing(r.message);document.querySelector('#risk-list').innerHTML=r.items?.map(x=>`<article class="risk-card ${x.risk_level==='红'?'red':x.risk_level==='黄'?'yellow':'gray'}"><b>${x.risk_level} · ${x.category}</b><span>${x.title}</span><span>${x.explanation}</span><a href="${x.url}" target="_blank" rel="noopener">查看公告原文 ↗</a><small>${x.published_date} · ${x.catalog_source}/${x.exchange} · 更新 ${x.updated_at}</small></article>`).join('')||researchMissing(r.message);if(val.status==='success'){const m=val.metrics,pct=x=>x==null?'暂无可靠数据':`${Number(x).toFixed(1)}%`;document.querySelector('#valuation-summary').innerHTML=[['PE(TTM)',m.pe_ttm==null?'暂无可靠数据':`${m.pe_ttm.toFixed(2)}倍`],['PB',m.pb==null?'暂无可靠数据':`${m.pb.toFixed(2)}倍`],['PS(TTM)',m.ps_ttm==null?'暂无可靠数据':`${m.ps_ttm.toFixed(2)}倍`],['PE历史分位',pct(m.pe_percentile_pct)],['PB历史分位',pct(m.pb_percentile_pct)],['PS历史分位',pct(m.ps_percentile_pct)]].map(x=>`<article><small>${x[0]}</small><b>${x[1]}</b></article>`).join('');document.querySelector('#valuation-conclusion').innerHTML=`<div class="conclusion">${val.conclusion}</div>${sourceMeta(val)}`;const peers=val.industry_comparison?.peers||[],ops=val.industry_comparison?.peer_operating||[],peerRows=peers.map(x=>({name:x['简称'],symbol:x['代码'],pe:x['市盈率-TTM'],pb:x['市净率-MRQ'],ps:x['市销率-TTM']}));document.querySelector('#valuation-peers').innerHTML=`<h4>同行估值比较</h4>${table(peerRows,[['公司','name'],['代码','symbol'],['PE(TTM)','pe'],['PB(MRQ)','pb'],['PS(TTM)','ps']])}<h4>同行经营指标比较</h4>${table(ops,[['公司','name'],['报告期','report_date'],['营收同比%','revenue_yoy_pct'],['利润同比%','profit_yoy_pct'],['毛利率%','gross_margin_pct'],['年化ROE%','roe_annualized_pct']])}<p class="hint">${val.industry_comparison?.operating_note||'暂无可靠数据'}</p>`;document.querySelector('#valuation-scenarios').innerHTML=val.scenarios?Object.entries(val.scenarios).map(([name,x])=>`<article class="scenario-card"><h4>${name}情景</h4><b>隐含利润年增速 ${x.implied_annual_profit_growth_pct}%</b><span>三年后假设 PE：${x.three_year_target_pe}倍</span><small>${x.explanation}</small></article>`).join(''):researchMissing()}else{document.querySelector('#valuation-summary').innerHTML=researchMissing(val.message);document.querySelector('#valuation-conclusion').innerHTML='';document.querySelector('#valuation-peers').innerHTML='';document.querySelector('#valuation-scenarios').innerHTML=''}document.querySelector('#industry-summary').innerHTML=industry.status==='success'?`<div class="conclusion">${industry.summary}</div>`:researchMissing(industry.message);const evidence=Object.entries(industry.evidence_by_topic||{}).flatMap(([topic,items])=>items.map(x=>({topic,...x})));document.querySelector('#industry-evidence').innerHTML=evidence.map(x=>`<article class="evidence-card"><h4>${x.topic} · ${x.information_type}</h4><span>${x.content}</span>${x.source_url?`<a href="${x.source_url}" target="_blank" rel="noopener">查看证据 ↗</a>`:''}<small>${x.source_date||'日期暂无'} · ${x.source_name} · 更新 ${x.updated_at}</small></article>`).join('')||researchMissing();document.querySelector('#industry-validation').innerHTML=(industry.validation_indicators||[]).map(x=>`<li>${x}</li>`).join('');document.querySelector('#industry-invalidation').innerHTML=(industry.invalidation_conditions||[]).map(x=>`<li>${x}</li>`).join('');document.querySelector('#industry-timeline').innerHTML=(industry.timeline||[]).map(x=>`<article><b>${x.source_date} · ${x.information_type}</b><p>${x.content}</p>${x.source_url?`<a href="${x.source_url}" target="_blank" rel="noopener">证据链接 ↗</a>`:''}</article>`).join('')||researchMissing();document.querySelector('#company-json').textContent=JSON.stringify(data,null,2);document.querySelector('#company-developer').open=false;requestAnimationFrame(()=>{if(f.chart?.length){drawResearchChart('financial-amount-chart',f.chart,[{key:'revenue',name:'营收',color:'#d6ad5d'},{key:'profit',name:'利润',color:'#d9363e'},{key:'cash_flow',name:'现金流',color:'#58a6ff'}],1e8);drawResearchChart('financial-ratio-chart',f.chart,[{key:'gross_margin_pct',name:'毛利率',color:'#d6ad5d'},{key:'roe_pct',name:'ROE',color:'#d9363e'},{key:'debt_ratio_pct',name:'负债率',color:'#58a6ff'}])}})}
async function loadCompanyResearch(symbol){companyResearchSymbol=symbol;const status=document.querySelector('#company-status');status.textContent='正在读取公司研究数据…';try{const data=await json(`/api/v1/company-research/${symbol}`);r=data.risk_radar;showCompanyReport(data);status.textContent=`${data.company.name||symbol} · 报告已生成`}catch(x){status.textContent=x.message}}
document.querySelector('#company-research-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.target),symbol=form.get('symbol'),include=form.get('include_documents')==='on',status=document.querySelector('#company-status');companyResearchSymbol=symbol;status.textContent='正在同步财报、公告、估值和产业证据，请稍候…';try{const sync=await json(`/api/v1/company-research/${symbol}/sync?include_documents=${include}`,{method:'POST'});status.textContent=`同步完成：${Object.entries(sync.sections).map(([k,v])=>`${k}=${v.status}`).join(' · ')}`;await loadCompanyResearch(symbol)}catch(x){status.textContent=x.message}});
