let technicalSymbol='';
function drawKline(rows){const canvas=document.querySelector('#kline-chart');if(!canvas||!rows.length)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,p={l:55,r:15,t:20,b:35};ctx.fillStyle='#101a23';ctx.fillRect(0,0,w,h);const values=rows.flatMap(x=>[x.High,x.Low]).filter(Number.isFinite),min=Math.min(...values),max=Math.max(...values),toY=v=>p.t+(max-v)/(max-min)*(h-p.t-p.b),step=(w-p.l-p.r)/rows.length;ctx.strokeStyle='#344451';ctx.fillStyle='#93a4b1';ctx.font='12px sans-serif';for(let i=0;i<5;i++){const y=p.t+i*(h-p.t-p.b)/4,price=max-i*(max-min)/4;ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(w-p.r,y);ctx.stroke();ctx.fillText(price.toFixed(2),4,y+4)}rows.forEach((x,i)=>{const cx=p.l+i*step+step/2,color=x.Close>=x.Open?'#d9363e':'#159957';ctx.strokeStyle=color;ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(cx,toY(x.High));ctx.lineTo(cx,toY(x.Low));ctx.stroke();const top=toY(Math.max(x.Open,x.Close)),bottom=toY(Math.min(x.Open,x.Close));ctx.fillRect(cx-Math.max(1,step*.28),top,Math.max(2,step*.56),Math.max(1,bottom-top))});[['SMA_20','#d6ad5d'],['SMA_60','#58a6ff']].forEach(([key,color])=>{ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.beginPath();let started=false;rows.forEach((x,i)=>{if(x[key]==null)return;const cx=p.l+i*step+step/2,y=toY(x[key]);started?ctx.lineTo(cx,y):ctx.moveTo(cx,y);started=true});ctx.stroke()});ctx.fillStyle='#93a4b1';ctx.fillText(rows[0].date,p.l,h-10);ctx.fillText(rows.at(-1).date,w-90,h-10)}
function showTechnical(data){drawKline(data.chart);const levels=items=>items.map(x=>`<li><b>${x.zone_type}</b> ${x.lower}～${x.upper} · ${x.strength} · 独立触碰${x.touches}次 · 衰减权重${x.weighted_touches} · 最近${x.last_touch_date||'无'} · ${x.basis.join('/')}</li>`).join('')||'<li>暂无可靠区间</li>';const period=data.kline_period,up=data.level_conditions.breakout_confirmation,down=data.level_conditions.breakdown_confirmation;document.querySelector('#technical-summary').innerHTML=`<div class="cards"><article><small>实时参考价</small><b>${data.current_price}</b><span>${data.current_price_source} · ${data.current_price_updated_at}</span></article><article><small>分析日期 / 当日收盘</small><b>${data.analysis_date} · ${data.analysis_close}</b></article><article><small>K线周期</small><b>${period.frequency} · ${period.bars}根</b><span>${period.start} ～ ${period.end} · ${data.adjustment}</span></article><article><small>综合结论</small><b>${data.conclusion}</b></article><article><small>均线 / MACD</small><b>${data.signals.ma_alignment} · ${data.signals.macd_state}</b></article><article><small>RSI / 量比</small><b>${data.indicators.rsi14} · ${data.indicators.volume_ratio}</b></article></div><div class="level-list"><div><h3>支撑区域（实时价下方）</h3><ul>${levels(data.support_levels)}</ul></div><div><h3>压力区域（实时价上方）</h3><ul>${levels(data.resistance_levels)}</ul></div><div><h3>震荡/争夺区</h3><ul>${levels(data.contest_zones)}</ul></div></div><div class="level-list"><div><h3>突破确认</h3><p>${up.rule}</p><p><b>失效：</b>${up.signal_invalidation||'暂无'}</p></div><div><h3>跌破确认</h3><p>${down.rule}</p><p><b>失效：</b>${down.signal_invalidation||'暂无'}</p></div></div>`;document.querySelector('#technical-result').textContent=JSON.stringify({signals:data.signals,conflicts:data.conflicts,level_conditions:data.level_conditions,risk_notice:data.risk_notice},null,2)}
function showSignalBacktest(data){const rows=Object.entries(data.signals).map(([name,x])=>({name,...x}));document.querySelector('#signal-table').innerHTML=table(rows,[['信号','name'],['出现次数','signal_count'],['完成样本','completed_samples'],['前瞻胜率%','forward_win_rate_pct'],['平均收益%','average_forward_return_pct'],['组合收益%','portfolio_return_pct'],['最大回撤%','portfolio_max_drawdown_pct'],['基准收益%','benchmark_return_pct']]);document.querySelector('#technical-result').textContent=data.warning}
document.querySelector('#technical-form')?.addEventListener('submit',async e=>{e.preventDefault();technicalSymbol=new FormData(e.target).get('symbol');try{showTechnical(await json(`/api/v1/technical/${technicalSymbol}`))}catch(x){document.querySelector('#technical-result').textContent=x.message}});
document.querySelector('#signal-backtest-button')?.addEventListener('click',async()=>{if(!technicalSymbol)return toast('请先分析一个股票代码');const out=document.querySelector('#technical-result');out.textContent='vectorbt 正在回测各项信号…';try{showSignalBacktest(await json(`/api/v1/technical/${technicalSymbol}/backtest`,{method:'POST'}))}catch(x){out.textContent=x.message}});
