let currentPlanPreview=null,currentPlanPayload=null,currentPlanAiId=null;
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const planStatusLabel={READY:'满足条件，可进入计划中的试错仓',WAIT:'等待指定条件',NO_TRADE:'不符合规则，放弃交易',INSUFFICIENT_DATA:'数据不足，无法判断'};
function drawPlanKline(rows,pattern){const canvas=document.querySelector('#plan-kline-chart');if(!canvas||!rows.length)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,p={l:58,r:18,t:20,b:32},values=rows.flatMap(x=>[x.high,x.low]),min=Math.min(...values),max=Math.max(...values),toY=v=>p.t+(max-v)/(max-min||1)*(h-p.t-p.b),step=(w-p.l-p.r)/rows.length;ctx.fillStyle='#101a23';ctx.fillRect(0,0,w,h);rows.forEach((x,i)=>{const cx=p.l+i*step+step/2,color=x.close>=x.open?'#d9363e':'#159957';ctx.strokeStyle=color;ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(cx,toY(x.high));ctx.lineTo(cx,toY(x.low));ctx.stroke();ctx.fillRect(cx-Math.max(1,step*.25),toY(Math.max(x.open,x.close)),Math.max(2,step*.5),Math.max(1,Math.abs(toY(x.open)-toY(x.close))))});[[pattern.platform_upper,'平台上沿','#d6ad5d'],[pattern.platform_lower,'平台下沿','#58a6ff'],[pattern.turn_trigger_price,'转强触发','#d9363e']].forEach(([v,label,color])=>{if(v==null)return;ctx.strokeStyle=color;ctx.setLineDash([5,4]);ctx.beginPath();ctx.moveTo(p.l,toY(v));ctx.lineTo(w-p.r,toY(v));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=color;ctx.fillText(`${label} ${v}`,p.l+4,toY(v)-4)});ctx.fillStyle='#93a4b1';ctx.fillText(rows[0].date,p.l,h-8);ctx.fillText(rows.at(-1).date,w-88,h-8)}
function showTradePlan(data){currentPlanPreview=data;const c=data.position_calculation||{},p=data.pattern||{},buy=data.buy_plan||{},holding=data.existing_position||{};document.querySelector('#trade-plan-result').innerHTML=`<div class="result-head"><b>${esc(data.symbol)} ${esc(data.company_name)} · ${esc(planStatusLabel[data.status]||data.status)}</b>${statusPill(data.status==='READY'?'通过':data.status==='NO_TRADE'?'不通过':data.status==='WAIT'?'警告':'无法判断')}</div><div class="cards"><article><small>当前参考价 / 分析日期</small><b>${esc(holding.current_price??'数据不足')} · ${esc(data.data_date??'数据不足')}</b><span>前复权日线；60分钟数据尚未接入</span></article><article><small>计划买入区</small><b>${buy.buy_zone?.[0]??'—'} ～ ${buy.buy_zone?.[1]??'—'}</b><span>再次转强触发 ${buy.turn_trigger_price??'数据不足'}</span></article><article><small>硬止损</small><b>${buy.hard_stop??'数据不足'}</b><span>买入后禁止向下移动</span></article><article><small>可买 / 首次试错</small><b>${c.final_allowed_quantity??0} / ${c.trial_quantity??0} 股</b><span>${c.final_allowed_quantity<100?'当前风险设置不适合开仓':'A股100股整手取整'}</span></article><article><small>规则版本</small><b>${esc(data.rule.version)}</b><span>${esc(data.rule.name)}</span></article><article><small>当前持仓</small><b>${holding.exists?`${holding.quantity}股 · 成本${holding.cost_price}`:'未持仓'}</b><span>${esc(holding.note)}</span></article></div><div class="conclusion"><b>主要原因：</b>${data.status_reason.map(esc).join('；')}<br><b>下一步观察：</b>${data.next_observations.map(esc).join('；')}</div><h3>12道交易闸门</h3><div class="risk-grid">${data.gates.map(x=>`<article class="plan-card"><h4>${esc(x.name)} ${statusPill(x.status)}</h4><span>${esc(x.evidence)}</span>${x.missing_conditions.length?`<small>缺失：${x.missing_conditions.map(esc).join('、')}</small>`:''}<small>来源：${esc(x.source)} · 数据时间：${esc(x.data_time)}</small></article>`).join('')}</div><h3>多周期状态</h3><div class="cards">${Object.entries(data.multi_timeframe).map(([k,v])=>`<article><small>${esc(k)}</small><b>${esc(v.state)}</b><span>${esc(v.evidence)}</span></article>`).join('')}</div><h3>仓位完整计算</h3><div class="table-wrap">${table(Object.entries(c).filter(([k])=>k!=='formula').map(([item,value])=>({item,value})),[['限制或结果','item'],['数量/金额','value']])}</div><div class="conclusion">${esc(c.formula||'缺少有效买入价或止损，无法计算仓位')}<br>最大计划风险：¥${((c.final_allowed_quantity||0)*(c.per_share_risk||0)).toFixed(2)}；首次试错金额：¥${c.trial_amount??0}。</div><h3>止损、确认加仓与退出</h3><div class="risk-grid"><article class="plan-card"><h4>结构与逻辑失效</h4><span>${esc(buy.structure_invalidation)}</span><span>${esc(buy.logic_invalidation)}</span></article><article class="plan-card"><h4>确认加仓 ${statusPill(data.confirmation_add.allowed?'通过':'不通过')}</h4><span>${data.confirmation_add.requirements.map(esc).join('；')}</span><small>禁止：${data.confirmation_add.prohibited.map(esc).join('；')}</small></article><article class="plan-card"><h4>第一减仓</h4><span>${esc(data.exit_plan.first_reduction)}</span><small>${esc(data.exit_plan.trailing_stop)}</small></article><article class="plan-card"><h4>清仓/逻辑退出</h4><span>${data.exit_plan.final_exit.map(esc).join('；')}</span></article></div><h3>放弃交易条件</h3><ul>${buy.abandon_conditions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="data-meta">${data.sources.map(x=>`<span>来源：${esc(x.name)} · 数据日期：${esc(x.data_date||'缺失')} · 更新时间：${esc(x.fetched_at||'缺失')} · ${x.stale?'过期/不足':'可用'}</span>`).join('')}</div>`;document.querySelector('#trade-plan-json').textContent=JSON.stringify(data,null,2);document.querySelector('#plan-actions').hidden=false;const shell=document.querySelector('#plan-chart-shell');shell.hidden=!data.chart.length;if(data.chart.length)requestAnimationFrame(()=>drawPlanKline(data.chart,p));loadPlanHistory(data.symbol,currentPlanPayload.account_id)}
function planCard(x){return `<article class="plan-card"><h4>${x.symbol} ${x.name||''} · ${x.trade_mode}</h4>${statusPill(x.status==='READY'?'通过':x.status==='BLOCKED'?'不通过':'无法判断')}<span>买入区 ${x.buy_zone[0]}—${x.buy_zone[1]} · 硬止损 ${x.initial_stop}</span><span>数量 ${x.planned_quantity} 股 · 风险 ¥${x.planned_risk_amount.toFixed(2)}</span><b>下一步：${x.next_action}</b>${dataMeta(x)}</article>`}
async function loadTradePlans(){const [rule,plans]=await Promise.all([json('/api/v1/trade-plan-generator/rules'),json('/api/v1/trade-plans')]);const p=rule.parameters;document.querySelector('#rule-version-card').innerHTML=`<div class="conclusion"><b>平台突破—回踩确认规则 ${rule.version}</b><br>平台至少 ${p.platform_min_days} 日；放量 ${p.breakout_volume_multiple} 倍；最低盈亏比 ${p.minimum_reward_risk}:1；最大止损距离 ${p.maximum_stop_distance_pct}%。参数已版本化，不是收益保证。</div>`;document.querySelector('#trade-plan-list').innerHTML=plans.length?plans.map(planCard).join(''):'<div class="missing-data">尚无交易计划。</div>'}
function planRequest(form){const o=Object.fromEntries(new FormData(form));['account_id','risk_pct','max_position_pct','max_total_position_pct','max_industry_position_pct'].forEach(k=>o[k]=Number(o[k]));if(!o.logic_invalidation)o.logic_invalidation=null;return o}
document.querySelector('#trade-plan-form')?.addEventListener('submit',async e=>{e.preventDefault();currentPlanPayload=planRequest(e.target);currentPlanAiId=null;document.querySelector('#trade-plan-result').innerHTML='<div class="missing-data">正在读取真实行情并执行确定性规则…</div>';try{showTradePlan(await json('/api/v1/trade-plan-generator/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(currentPlanPayload)}))}catch(x){document.querySelector('#trade-plan-result').innerHTML=`<div class="missing-data">计划生成失败：${esc(x.message)}</div>`}});
async function loadPlanHistory(symbol,accountId){const rows=await json(`/api/v1/trade-plan-generator/history?account_id=${accountId}&symbol=${symbol}`);document.querySelector('#plan-history').innerHTML=rows.length?rows.map(x=>`<article class="plan-card"><b>版本 ${x.plan_version} · ${esc(x.status)}</b><span>执行状态：${esc(x.execution_status||'未跟踪')}</span><span>买入区 ${x.buy_zone.join('—')} · 止损 ${x.stop}</span><small>计划 #${x.id} · 规则 ${esc(x.rule_version)} · 创建 ${esc(x.created_at)}</small><button type="button" class="view-plan-execution" data-plan-id="${x.id}">查看执行记录</button></article>`).join(''):'<div class="missing-data">该账户尚未保存此股票的计划。</div>';document.querySelectorAll('.view-plan-execution').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#execution-plan-id').value=button.dataset.planId;loadPlanExecution(button.dataset.planId)}))}
const executionStatusLabels={draft:'草稿',confirmed:'已确认',waiting_entry:'等待买入',entry_triggered:'买入条件触发',partially_executed:'部分成交',holding:'持仓中',add_triggered:'确认加仓触发',reduce_triggered:'减仓条件触发',stop_triggered:'硬止损触发',take_profit_triggered:'止盈条件触发',invalidated:'计划失效',closed:'已结束'};
async function loadPlanExecution(planId){if(!planId)return toast('请填写计划ID');const data=await json(`/api/v1/trade-plans/${planId}/execution`),s=data.summary||{},violations=s.violations||[];document.querySelector('#plan-execution-result').innerHTML=`<div class="cards"><article><small>执行状态</small><b>${esc(executionStatusLabels[data.execution_status]||data.execution_status)}</b></article><article><small>当前跟踪持仓</small><b>${s.net_quantity||0} 股</b><span>平均成本 ${s.average_cost??'—'}</span></article><article><small>计划/执行价格偏差</small><b>${s.entry_price_deviation_pct==null?'—':s.entry_price_deviation_pct+'%'}</b></article><article><small>已实现R收益</small><b>${s.realized_r==null?'—':s.realized_r+'R'}</b><span>盈亏 ¥${s.realized_pnl??0}</span></article><article><small>规则执行率</small><b>${s.rule_execution_rate}%</b></article><article><small>计划完整率</small><b>${s.plan_completeness}%</b></article></div><h4>执行偏差</h4>${violations.length?`<div class="risk-grid">${violations.map(x=>`<article class="risk-card red"><b>${esc(x.code)}</b><span>${esc(x.message)}</span></article>`).join('')}</div>`:'<div class="missing-data">当前记录未识别出超仓、亏损补仓、提前买入或未执行止损。</div>'}<h4>手工成交</h4><div class="table-wrap">${table(data.fills,[['时间','executed_at'],['方向','side'],['数量','quantity'],['价格','price'],['原因','reason'],['测试','is_test']])}</div><details class="developer-details"><summary>执行事件详情</summary><pre>${esc(JSON.stringify(data.events,null,2))}</pre></details>`}
document.querySelector('#load-plan-execution')?.addEventListener('click',()=>loadPlanExecution(document.querySelector('#execution-plan-id').value));
document.querySelector('#plan-fill-form')?.addEventListener('submit',async event=>{event.preventDefault();const planId=document.querySelector('#execution-plan-id').value;if(!planId)return toast('请先选择已保存计划');const raw=Object.fromEntries(new FormData(event.target));const payload={side:raw.side,quantity:Number(raw.quantity),price:Number(raw.price),fee:Number(raw.fee||0),executed_at:new Date(raw.executed_at).toISOString(),reason:raw.reason,trigger_confirmed:raw.trigger_confirmed===''?null:raw.trigger_confirmed==='true',is_test:event.target.elements.is_test.checked,notes:raw.notes||null};try{const data=await json(`/api/v1/trade-plans/${planId}/execution/fills`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});toast('成交已记录并重新检查执行偏差');await loadPlanExecution(data.plan_id)}catch(error){toast(error.message)}});
document.querySelector('#plan-execution-evaluate')?.addEventListener('submit',async event=>{event.preventDefault();const planId=document.querySelector('#execution-plan-id').value;if(!planId)return toast('请先选择已保存计划');const raw=Object.fromEntries(new FormData(event.target)),payload={current_price:raw.current_price?Number(raw.current_price):null,entry_triggered:false,add_triggered:false,reduce_triggered:false,stop_triggered:false,take_profit_triggered:false,invalidated:false,evidence:raw.evidence||null};if(raw.event)payload[raw.event]=true;try{await json(`/api/v1/trade-plans/${planId}/execution/evaluate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});toast('执行状态与偏差已更新');await loadPlanExecution(planId)}catch(error){toast(error.message)}});
document.querySelector('#save-generated-plan')?.addEventListener('click',async()=>{if(!currentPlanPreview)return;try{const data=await json('/api/v1/trade-plan-generator/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...currentPlanPayload,preview_hash:currentPlanPreview.preview_hash,ai_analysis_id:currentPlanAiId})});toast(`计划版本 ${data.plan_version} 已冻结保存`);await loadTradePlans();await loadPlanHistory(currentPlanPreview.symbol,currentPlanPayload.account_id)}catch(x){toast(x.message)}});
function showPlanAI(data){const out=document.querySelector('#plan-ai-result');if(data.status!=='success'){out.className='missing-data';out.textContent=data.error||'大模型分析失败；规则引擎计划仍可使用。';return}currentPlanAiId=data.id;out.className='';out.innerHTML=aiExplanation(data)}
document.querySelector('#run-plan-ai')?.addEventListener('click',async()=>{if(!currentPlanPreview)return;const out=document.querySelector('#plan-ai-result');out.className='missing-data';out.textContent='AI 正在归纳证据；规则计划已可独立使用…';try{showPlanAI(await json('/api/v1/trade-plan-generator/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...currentPlanPayload,preview_hash:currentPlanPreview.preview_hash})}))}catch(x){out.textContent=`AI辅助分析失败：${x.message}；规则计划仍可使用。`}});
function positionCard(x){return `<article class="risk-card ${x.hard_stop_triggered?'red':x.trade_plan_id?'gray':'yellow'}"><b>${x.symbol} ${x.name} · ${x.stage}</b><span>逻辑：${x.logic_status} · ${x.hard_stop_triggered?'硬止损已触发':'硬止损未触发'} · ${x.allow_add?'允许按计划加仓':'不允许加仓'}</span><span>仓位 ${x.position_pct.toFixed(2)}% · 风险敞口 ${x.risk_exposure_pct==null?'数据不足':x.risk_exposure_pct.toFixed(2)+'%'}</span><strong>下一步：${x.next_action}</strong><small>原计划 ${x.trade_plan_id||'缺失'} · 规则版本 ${x.rule_version||'缺失'}</small>${dataMeta(x)}</article>`}
async function loadPositions(persist=false){const id=document.querySelector('#position-account')?.value,url=`/api/v1/positions/${persist?'snapshots':'management'}${id?`?account_id=${id}`:''}`,data=await json(url,persist?{method:'POST'}:{});document.querySelector('#position-management').innerHTML=data.length?data.map(positionCard).join(''):'<div class="missing-data">暂无持仓。</div>';if(persist)toast('今日持仓状态快照已保存')}
document.querySelector('#position-refresh')?.addEventListener('click',()=>loadPositions().catch(x=>toast(x.message)));document.querySelector('#position-snapshot')?.addEventListener('click',()=>loadPositions(true).catch(x=>toast(x.message)));
async function loadDashboard(){const d=await json('/api/v1/dashboard/summary'),m=d.market;document.querySelector('#dashboard-market').innerHTML=`<article><small>市场状态</small><b>${m.state}</b><span>${m.explanation}</span></article><article><small>风险状态</small><b>${m.risk_state}</b><span>由当前持仓严重风险推导，不代表市场预测</span></article><article><small>缺失证据</small><b>${m.missing_data.length} 项</b><span>${m.missing_data.join('、')}</span></article>${dataMeta(m)}`;document.querySelector('#dashboard-priorities').innerHTML=d.priorities.map(x=>`<div>${x}</div>`).join('');document.querySelector('#dashboard-holdings').innerHTML=d.holding_risks.length?d.holding_risks.map(positionCard).join(''):'<div class="conclusion">当前未发现硬止损或缺计划持仓。</div>';document.querySelector('#dashboard-plans').innerHTML=d.near_plans.length?d.near_plans.map(x=>`<article class="plan-card"><b>${x.symbol} ${x.name||''}</b><span>现价 ${x.price}，计划区 ${x.buy_zone.join('—')}</span>${statusPill(x.status)}${dataMeta(x)}</article>`).join(''):'<div class="missing-data">没有候选股接近计划区，或行情数据不足。</div>';document.querySelector('#dashboard-discipline').innerHTML=`<article><small>今日纪律事件</small><b>${d.discipline.today_violations}</b></article><article><small>计划外交易</small><b>${d.discipline.unplanned_trades}</b></article><article><small>当前纪律警报</small><b>${d.discipline.current_alerts.length}</b></article>`;document.querySelector('#dashboard-data-issues').innerHTML=d.data_issues.length?d.data_issues.map(x=>`<article class="risk-card yellow"><b>${x.source} · ${x.status}</b><span>${x.message}</span><small>${x.api} · 更新 ${x.updated_at}</small></article>`).join(''):'<div class="conclusion">当前未记录失败或超过24小时的行情数据。</div>'}
function showSettings(data){document.querySelector('#settings-result').innerHTML=Object.entries(data).filter(([k])=>k!=='secrets').map(([k,v])=>`<article><small>${k}</small><b>${v}</b><span>获取状态：${v==='not_configured'?'未配置':'可用'}</span></article>`).join('');document.querySelector('#settings-json').textContent=JSON.stringify(data,null,2)}
document.querySelector('#llm-test-button')?.addEventListener('click',async()=>{const out=document.querySelector('#llm-test-result');out.textContent='正在验证鉴权、模型和结构化输出…';try{const data=await json('/api/v1/settings/llm/test',{method:'POST'});out.innerHTML=`<div class="conclusion">连接成功：${esc(data.provider)} / ${esc(data.model)} · 结构化输出正常 · ${data.duration_ms}ms</div>`}catch(x){out.innerHTML=`<div class="missing-data">连接失败：${esc(x.message)}</div>`}});
function initializeBacktestDates(){const end=document.querySelector('#backtest-date-to'),start=document.querySelector('#backtest-date-from');if(!end||end.value)return;const now=new Date(),past=new Date(now);past.setFullYear(now.getFullYear()-3);past.setDate(past.getDate()-1);end.value=now.toISOString().slice(0,10);start.value=past.toISOString().slice(0,10);updateRulePreview()}
async function loadPage(){if(page==='dashboard')await loadDashboard();if(page==='holdings')await loadPositions();if(page==='trade-plans')await loadTradePlans();if(page==='trades'){const rows=await json('/api/v1/trades');document.querySelector('#trades-table').innerHTML=table(rows,[['时间','traded_at'],['股票','symbol'],['方向','side'],['数量','quantity'],['价格','price'],['计划内','is_planned'],['情绪','emotion']])}if(page==='x-monitor'){const st=await json('/api/v1/settings/status');document.querySelector('#x-status').textContent=`凭据状态：${st.x}`;const rows=await json('/api/v1/x/posts');document.querySelector('#posts-table').innerHTML=table(rows,[['时间','published_at'],['作者','author'],['内容','content'],['链接','url']])}if(page==='backtests'){initializeBacktestDates();const rows=(await json('/api/v1/backtests')).map(x=>({...x,strategy_name:strategyNames[x.strategy]||x.strategy,sample:x.metrics?.sample?.label||''}));document.querySelector('#backtests-table').innerHTML=table(rows,[['股票','symbol'],['交易规则','strategy_name'],['开始','date_from'],['结束','date_to'],['样本判断','sample'],['状态','status']])}if(page==='settings')showSettings(await json('/api/v1/settings/status'))}

const oneClickRuns={};
const pipelineNames=['行情数据','市场判断','行业判断','个股分析','风险计算','AI解释','生成计划'];
function renderPipeline(target,steps=[],active=-1){const byName=Object.fromEntries(steps.map(x=>[x.name,x]));target.innerHTML=pipelineNames.map((name,index)=>{const item=byName[name],state=item?.status||(index===active?'running':index<active?'success':'pending'),label={success:'完成',partial:'降级',failed:'失败',skipped:'跳过',running:'进行中',pending:'等待'}[state]||state;return `<article class="pipeline-step ${state}"><b>${index+1}. ${name}</b><span>${label}</span>${item?`<small>${esc(item.detail)}</small>`:''}</article>`}).join('')}
function oneClickPayload(form){const raw=Object.fromEntries(new FormData(form)),number=k=>raw[k]===''||raw[k]==null?null:Number(raw[k]);return{symbol:raw.symbol,position_mode:raw.position_mode,account_id:number('account_id'),plan_capital:number('plan_capital')||300000,available_cash:null,holding_quantity:number('holding_quantity'),holding_cost_price:number('holding_cost_price'),refresh:form.elements.refresh?.checked||false,enable_ai:form.elements.enable_ai?.checked!==false,risk_pct:number('risk_pct')||0.5,max_position_pct:number('max_position_pct')||30,max_total_position_pct:number('max_total_position_pct')||80,max_industry_position_pct:number('max_industry_position_pct')||40,logic_invalidation:raw.logic_invalidation||null}}
function aiExplanation(ai){if(!ai||ai.status!=='success')return `<div class="missing-data">AI辅助解释未完成：${esc(ai?.error||'未配置或暂不可用')}。规则计划仍然有效。</div>`;const r=ai.result||{},claims=(items,title)=>`<article class="plan-card"><h4>${title}</h4>${items?.length?items.map(x=>`<p>${esc(x.claim)}<small>来源编号：${x.source_ids.map(esc).join('、')} · ${esc(x.confidence)}</small></p>`).join(''):'<span>尚未获取到充分资料。</span>'}</article>`,statements=(items,title)=>`<article class="plan-card"><h4>${title}</h4>${items?.length?items.map(x=>`<p><b>${esc(x.topic)}</b>：${esc(x.content)}<small>来源编号：${x.source_ids.map(esc).join('、')} · ${esc(x.confidence)}</small></p>`).join(''):'<span>暂无经过证据校验的内容。</span>'}</article>`;return `<div class="ai-label">AI辅助归纳 · Schema ${esc(r.schema_version||'未知')} · 不改变规则结论</div><div class="risk-grid">${statements(r.ai_summaries,'经营、财报与产业归纳')}${statements(r.ai_inferences,'AI推断（非原始事实）')}${claims(r.supporting_evidence,'支持证据')}${claims(r.opposing_evidence,'反方证据')}${claims(r.risk_events,'重大风险')}<article class="plan-card"><h4>信息冲突与缺失</h4><span>${(r.conflicts||[]).map(x=>esc(x.description)).join('；')||(r.missing_data||[]).map(esc).join('；')||'尚未识别冲突'}</span></article></div><div class="data-meta"><span>模型：${esc(ai.provider)}/${esc(ai.model)}</span><span>分析时间：${esc(ai.created_at)}</span><span>缓存：${ai.cache_hit?'命中':'未命中'}</span><span>Token：${ai.usage?.total_tokens??'未返回'}</span></div>`}
function renderOneClick(data,result,actions){const p=data.plan||{},d=data.decision||{},buy=p.buy_plan||{},c=p.position_calculation||{},holding=p.existing_position||{},market=p.market_assessment||{},industry=p.industry_assessment||{},missing=[...(p.missing_conditions||[]),...((p.research_inventory||{}).missing||[])],riskEvents=(p.research_inventory||{}).risk_events||[],rr=p.gates?.find(x=>x.code==='reward_risk'),first=p.exit_plan?.first_reduction||'数据不足，无法判断',second=p.exit_plan?.second_reduction||'达到更高R倍数后结合周线压力分批减仓';result.innerHTML=`<div class="decision-banner decision-${esc(d.status||'WAIT')}"><small>当前结论</small><h2>${esc(d.label||'等待观察')}</h2><p>${esc(d.next_action||'等待下一次有效触发。')}</p></div><div class="next-action"><b>下一步应该做什么：</b>${esc(d.next_action||'重新检查缺失数据')}</div><div class="cards"><article><small>当前价格 / 行情日期</small><b>${holding.current_price??'数据不足'} / ${esc(p.data_date||'缺失')}</b><span>前复权日线</span></article><article><small>市场环境</small><b>${esc(market.state||'无法判断')} · 风险${esc(market.risk||'无法判断')}</b><span>程序计算</span></article><article><small>行业强弱 / 主线代理</small><b>${esc(industry.state||'无法判断')} / ${industry.is_mainline===true?'是':industry.is_mainline===false?'否':'无法判断'}</b><span>${esc(industry.industry||'行业缺失')}</span></article><article><small>预期盈亏比</small><b>${esc(rr?.evidence||'数据不足')}</b></article></div><h3>买入与仓位计划（规则计算）</h3><div class="plan-summary-grid"><article><h4>允许试仓条件</h4><p>买入区：${buy.buy_zone?.[0]??'—'} ～ ${buy.buy_zone?.[1]??'—'}</p><p>触发价：${buy.turn_trigger_price??'数据不足'}</p><p>${esc(buy.trigger_condition||'数据不足')}</p></article><article><h4>首次试仓</h4><p>${c.trial_quantity??0} 股 · ¥${Number(c.trial_amount||0).toLocaleString()}</p><p>约占账户 ${c.trial_account_pct??0}%</p><p>最大计划亏损 ¥${Number(c.maximum_loss||0).toLocaleString()}</p></article><article><h4>止损与计划失效</h4><p>硬止损：${buy.hard_stop??'数据不足'}</p><p>${esc(buy.structure_invalidation||'数据不足')}</p><p>${esc(buy.logic_invalidation||'数据不足')}</p></article><article><h4>第一 / 第二止盈</h4><p>${esc(first)}</p><p>${esc(second)}</p></article></div><h3>确认加仓纪律</h3><div class="conclusion"><b>${p.confirmation_add?.allowed?'当前满足条件式加仓规则':'当前不允许加仓'}</b><br>必须：${(p.confirmation_add?.requirements||[]).map(esc).join('；')}<br>禁止：${(p.confirmation_add?.prohibited||[]).map(esc).join('；')}</div><h3>规则证据</h3><div class="risk-grid">${(p.gates||[]).map(x=>`<article class="plan-card"><h4>${esc(x.name)} ${statusPill(x.status)}</h4><span>${esc(x.evidence)}</span><small>规则计算 · 来源：${esc(x.source)} · ${esc(x.data_time)}</small></article>`).join('')}</div><h3>重大风险与缺失数据</h3>${riskEvents.length?`<div class="risk-grid">${riskEvents.map(x=>`<article class="risk-card ${x.risk_level==='红'?'red':'yellow'}"><b>${esc(x.risk_level)} · ${esc(x.title)}</b><small>${esc(x.published_date)} · ${esc(x.source)}</small>${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener">查看原文 ↗</a>`:''}</article>`).join('')}</div>`:'<div class="missing-data">本地尚未取得已分类重大风险事件，不代表不存在风险。</div>'}<div class="missing-data">${missing.length?`仍缺少：${[...new Set(missing)].map(esc).join('、')}`:'关键规则数据已取得。'}</div><h3>AI解释与反方证据</h3>${aiExplanation(data.ai)}<details class="developer-details"><summary>技术详情 / 原始结构化结果</summary><pre>${esc(JSON.stringify(data,null,2))}</pre></details>`;actions.hidden=false;const button=actions.querySelector('.confirm-one-click-plan'),reason=actions.querySelector('.save-reason');button.disabled=!data.can_save;button.title=data.save_disabled_reason||'';reason.textContent=data.can_save?'保存后冻结当前行情、规则、账户、证据和AI版本。':data.save_disabled_reason;oneClickRuns[actions.id]=data.run_id;if(document.querySelector('#trade-plan-json'))document.querySelector('#trade-plan-json').textContent=JSON.stringify(data,null,2);if(p.chart?.length&&page==='trade-plans'){document.querySelector('#plan-chart-shell').hidden=false;requestAnimationFrame(()=>drawPlanKline(p.chart,p.pattern||{}))}}
async function loadOneClickAccounts(){const accounts=await json('/api/v1/accounts'),remembered=localStorage.getItem('lastPlanAccount');document.querySelectorAll('.one-click-account').forEach(select=>{select.innerHTML='<option value="">自动选择上次账户</option>'+accounts.map(x=>`<option value="${x.id}">${esc(x.name)} · 权益¥${Number(x.total_assets).toLocaleString()}</option>`).join('');if(remembered&&accounts.some(x=>String(x.id)===remembered))select.value=remembered})}
async function prefillHolding(form){if(form.elements.position_mode.value!=='持仓')return;const accountId=form.elements.account_id.value,symbol=form.elements.symbol.value;if(!accountId||!/^[0-9]{6}$/.test(symbol))return;try{const rows=await json('/api/v1/holdings'),item=rows.find(x=>String(x.account_id)===accountId&&x.symbol===symbol);if(item){form.elements.holding_quantity.value=item.quantity;form.elements.holding_cost_price.value=item.cost_price}}catch(_){}}
document.querySelectorAll('.one-click-plan-form').forEach(form=>{const toggle=()=>{const held=form.elements.position_mode.value==='持仓';form.querySelectorAll('.holding-field').forEach(x=>x.hidden=!held);form.elements.holding_quantity.required=held;form.elements.holding_cost_price.required=held;if(held)prefillHolding(form)};form.elements.position_mode.addEventListener('change',toggle);form.elements.symbol.addEventListener('blur',()=>prefillHolding(form));form.elements.account_id.addEventListener('change',()=>{if(form.elements.account_id.value)localStorage.setItem('lastPlanAccount',form.elements.account_id.value);prefillHolding(form)});toggle();form.addEventListener('submit',async event=>{event.preventDefault();const result=document.getElementById(form.dataset.result),progress=document.getElementById(form.dataset.progress),actions=document.getElementById(form.dataset.actions),button=form.querySelector('.primary-action');actions.hidden=true;button.disabled=true;button.title='分析正在进行，请等待完成';let active=0;renderPipeline(progress,[],active);const timer=setInterval(()=>{active=Math.min(active+1,pipelineNames.length-1);renderPipeline(progress,[],active)},1400);result.innerHTML='<div class="missing-data">正在自动获取真实数据并执行规则。任一步失败都会显示降级原因，不会伪造结论。</div>';try{const data=await json('/api/v1/trade-plan-generator/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(oneClickPayload(form))});clearInterval(timer);renderPipeline(progress,data.steps);renderOneClick(data,result,actions);currentPlanPreview=data.plan;currentPlanPayload=data.generator_request;if(data.account?.id)localStorage.setItem('lastPlanAccount',String(data.account.id));if(page==='trade-plans')await loadPlanHistory(data.plan.symbol,data.account.id)}catch(error){clearInterval(timer);renderPipeline(progress,[],0);result.innerHTML=`<div class="missing-data">分析失败：${esc(error.message)}。请检查数据源设置后重试。</div>`}finally{button.disabled=false;button.title=''}})});
document.querySelectorAll('.confirm-one-click-plan').forEach(button=>button.addEventListener('click',async()=>{const actions=button.closest('.action-row'),runId=oneClickRuns[actions.id];if(!runId)return toast('请先完成一次分析');button.disabled=true;try{const saved=await json(`/api/v1/trade-plan-generator/analyze/${runId}/confirm`,{method:'POST'});toast(`计划版本 ${saved.plan_version} 已冻结保存`);actions.querySelector('.save-reason').textContent=`已保存为计划 #${saved.id}，版本 ${saved.plan_version}`;if(page==='trade-plans'){await loadTradePlans();await loadPlanHistory(saved.symbol,saved.account_id)}}catch(error){toast(error.message);button.disabled=false}}));
loadOneClickAccounts().catch(e=>toast(`账户读取失败：${e.message}`));
loadBase();loadPage().catch(e=>toast(e.message));
